# Copia real de usuarios antes de cada cambio, segundo administrador y correo de recuperacion. Uso: python3 fix13.py
import os,subprocess,sys,base64,shutil,time
API='/var/www/vibkaptur/public/api'; PRIV='/var/www/vibkaptur/private'
F={'miclave.php':'','usuarios.php':''}
for n,c in F.items():
    open('/tmp/_'+n,'wb').write(base64.b64decode(c))
    if subprocess.run(['php','-l','/tmp/_'+n],capture_output=True).returncode!=0: print('FALLO de sintaxis en',n,'. NO SE HA TOCADO NADA'); sys.exit(1)
os.makedirs('/root/vibk_api_antes',exist_ok=True)
ra=os.stat(os.path.join(API,'clave.php'))
for n in F:
    p=os.path.join(API,n); shutil.copy2(p,'/root/vibk_api_antes/'+n+'.antes_fix13'); shutil.copyfile('/tmp/_'+n,p); os.chown(p,ra.st_uid,ra.st_gid); os.chmod(p,ra.st_mode&0o7777)
uf=os.path.join(PRIV,'users.php'); bd=os.path.join(PRIV,'backups'); ru=os.stat(uf)
os.makedirs(bd,exist_ok=True); os.chown(bd,ru.st_uid,ru.st_gid)
print('COPIAS DE USUARIOS ACTIVADAS')
shutil.copy2(uf,'/root/users.php.antes_'+time.strftime('%Y%m%d_%H%M%S'))
php=r"""$f="/var/www/vibkaptur/private/users.php"; $u=include $f; $e="admin@ingenorsistemas.com"; $n="pedro.ortega@ingenorsistemas.com"; if(!isset($u[$e])){echo "AVISO: no existe admin@ingenorsistemas.com. No se ha creado nada\n"; exit;} $u[$e]["mail"]=$n; if(isset($u[$n])){ echo "AVISO: ya existia un usuario ".$n." (rol ".$u[$n]["role"]."). No lo he tocado\n"; } else { $x=$u[$e]; unset($x["mail"]); $x["name"]="Pedro Ortega"; $x["p"]=password_hash(bin2hex(random_bytes(24)),PASSWORD_BCRYPT); $u[$n]=$x; echo "SEGUNDO ADMINISTRADOR CREADO: ".$n." (sin contraseña todavia: se crea con el enlace de recuperacion)\n"; } file_put_contents($f,"<?php\n// VIBKAPTUR usuarios (servidor). Claves cifradas.\nreturn ".var_export($u,true).";\n"); echo "Recuperacion de admin@ingenorsistemas.com: el enlace llegara a ".$n." (".count($u)." usuarios)\n";"""
print(subprocess.run(['php','-r',php],capture_output=True,text=True).stdout.strip())
